INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63673824', 63673824, 'analyze_legacy', 'Kab. Sintang', 'kabkota', 'Sekretariat Daerah', 'Belanja Modal Alat Rumah Tangga Lainnya (Home Use)', 'Barang', 'E-Purchasing', 'Kalimantan Barat, Sintang (Kab.)', 110001000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Modal Alat Rumah Tangga Untuk Keperluan Rumah Jabatan Bupati, Rumah Jabatan Wakil Bupati dan Sekretariat Daerah, Tahun Anggaran 2026', 'Gorder/Tirai Karpet Roll Cut / Permadani Dispenser Sprei Mesin Cuci', 110001000, 'high', 'Pengadaan perlengkapan rumah tangga untuk rumah jabatan seperti gorden, karpet, sprei, dispenser, dan mesin cuci berisiko tidak proporsional terhadap kebutuhan layanan publik, terutama karena dikemas sebagai satu paket belanja modal. Seluruh nilai paket layak dicermati sebagai potensi pemborosan sampai kebutuhan, standar barang, dan urgensinya dapat dibuktikan.', NULL, NULL, 3, 1, 1, 1, 1, 1078124);
