INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63611183', 63611183, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI PENGELOLA TRANSPORTASI DARAT KELAS II PAPUA', 'Belanja Penambah Daya Tahan Tubuh', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 52800000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Belanja Penambah Daya Tahan Tubuh (8 Orang) ( 2112, OH, @ 25000 );', 'Spesifikasi Pekerjaan Belanja Penambah Daya Tahan Tubuh (2 Orang) (1 Tahun, @ Rp389.000) Pengadaan suplemen/vitamin penambah daya tahan tubuh bagi 2 (dua) orang pegawai untuk mendukung kesehatan dan kebugaran dalam pelaksanaan tugas selama 1 (satu) tahun anggaran. Ruang lingkup pengadaan meliputi: Suplemen kesehatan, multivitamin, atau produk sejenis yang berfungsi membantu menjaga daya tahan tubuh; Produk harus memiliki izin edar resmi (BPOM); Memiliki masa kedaluwarsa yang masih berlaku pada saat penyerahan; Dikemas dengan baik dan aman untuk dikonsumsi. Ketentuan: Jenis dan jumlah disesuaikan dengan kebutuhan serta ketentuan yang berlaku; Pengadaan dilaksanakan sesuai peraturan perundang-undangan; Tidak termasuk obat keras atau produk yang memerlukan resep dokter.', 51174000, 'high', 'Nilai anggaran tampak tidak selaras dengan uraian dan spesifikasi. Rincian menyebut 2.112 OH @ Rp25.000 untuk 8 orang, sehingga total mendekati pagu, namun spesifikasi lain hanya menyebut kebutuhan suplemen 2 orang selama 1 tahun @ Rp389.000. Ketidakkonsistenan volume dan satuan ini mengindikasikan penganggaran berlebihan untuk belanja suplemen pegawai.', NULL, NULL, 3, 1, 1, 1, 1, 1078126);
